-- Do not edit this file with real email addresses. Copy it into the SQL editor, replace the placeholders there, and run it.
-- Links accounts created in the Supabase dashboard (Authentication > Users) to profiles and memberships.
-- Run after seed.sql.

-- Manager of the first synthetic site
insert into public.profiles (id, role, display_name)
select u.id, 'manager', '시연 관리자'
from auth.users u
where u.email = '<manager-email>';

insert into public.site_members (site_id, profile_id)
select s.id, u.id
from public.sites s, auth.users u
where s.name = '합성 제1공장' and u.email = '<manager-email>';

-- Partner of the synthetic equipment company
insert into public.profiles (id, role, display_name)
select u.id, 'partner', '시연 파트너'
from auth.users u
where u.email = '<partner-email>';

insert into public.partner_members (partner_id, profile_id)
select p.id, u.id
from public.partners p, auth.users u
where p.company_name = '합성 설비 업체' and u.email = '<partner-email>';
